/// Команды печати (`src/print`) — команды самого приложения: Tauri создаёт им права `allow-…` (`permissions/
/// autogenerated`), окно получает их в `capabilities/default.json`; без права команда окну недоступна.
const COMMANDS: &[&str] = &["list_printers", "print_format", "print_pdf", "print_pages"];

fn main() {
    let manifest = tauri_build::AppManifest::new().commands(COMMANDS);
    if let Err(error) =
        tauri_build::try_build(tauri_build::Attributes::new().app_manifest(manifest))
    {
        panic!("tauri-build: {error:#}");
    }
}
